  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nenum Role {\n  PATIENT\n  DOCTOR\n  ADMIN\n}\n\nenum AppointmentStatus {\n  BOOKED\n  CANCELLED\n  COMPLETED\n}\n\nenum UrgencyLevel {\n  LOW\n  MEDIUM\n  HIGH\n}\n\nmodel User {\n  id                       String    @id @default(uuid())\n  email                    String    @unique\n  password                 String\n  name                     String\n  role                     Role      @default(PATIENT)\n  isVerified               Boolean   @default(false)\n  verificationToken        String?\n  verificationTokenExpires DateTime?\n  resetPasswordToken       String?\n  resetPasswordExpires     DateTime?\n\n  // Google Calendar OAuth credentials\n  googleAccessToken  String?\n  googleRefreshToken String?\n  googleTokenExpires DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  doctorProfile DoctorProfile?\n  appointments  Appointment[]        @relation(\"PatientAppointments\")\n  reminders     MedicationReminder[]\n  holds         SlotHold[]           @relation(\"UserHolds\")\n}\n\nmodel DoctorProfile {\n  id             String   @id @default(uuid())\n  userId         String   @unique\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  specialisation String\n  workingHours   Json? // Stores weekly schedule: { monday: [{start: \"09:00\", end: \"13:00\"}, {start: \"14:00\", end: \"17:00\"}], ... }\n  slotDuration   Int      @default(30) // In minutes\n  isActive       Boolean  @default(true) // For activating/deactivating\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  leaves       DoctorLeave[]\n  appointments Appointment[] @relation(\"DoctorAppointments\")\n}\n\nmodel DoctorLeave {\n  id        String        @id @default(uuid())\n  doctorId  String\n  doctor    DoctorProfile @relation(fields: [doctorId], references: [id], onDelete: Cascade)\n  date      DateTime // Date only (HH:MM set to 00:00)\n  reason    String?\n  createdAt DateTime      @default(now())\n\n  @@unique([doctorId, date])\n}\n\nmodel SlotHold {\n  id        String   @id @default(uuid())\n  doctorId  String\n  dateTime  DateTime\n  expiresAt DateTime\n  userId    String\n  user      User     @relation(\"UserHolds\", fields: [userId], references: [id], onDelete: Cascade)\n  status    String   @default(\"HELD\") // HELD, EXPIRED, RELEASED, BOOKED\n  active    Boolean? // true when active hold, null when expired/released\n\n  createdAt DateTime @default(now())\n\n  @@unique([doctorId, dateTime, active])\n}\n\nmodel Appointment {\n  id                    String            @id @default(uuid())\n  patientId             String\n  patient               User              @relation(\"PatientAppointments\", fields: [patientId], references: [id], onDelete: Cascade)\n  doctorId              String\n  doctor                DoctorProfile     @relation(\"DoctorAppointments\", fields: [doctorId], references: [id], onDelete: Cascade)\n  dateTime              DateTime // Start time\n  endTime               DateTime // End time\n  status                AppointmentStatus @default(BOOKED)\n  active                Boolean? // true when BOOKED, null when CANCELLED/COMPLETED\n  symptoms              String\n  googleCalendarEventId String?\n  createdAt             DateTime          @default(now())\n  updatedAt             DateTime          @updatedAt\n\n  preVisitSummary PreVisitSummary?\n  consultation    Consultation?\n\n  @@unique([doctorId, dateTime, active])\n}\n\nmodel PreVisitSummary {\n  id                 String        @id @default(uuid())\n  appointmentId      String        @unique\n  appointment        Appointment   @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n  urgency            UrgencyLevel?\n  chiefComplaint     String?\n  suggestedQuestions Json? // String[]\n  status             String        @default(\"PENDING\") // PENDING, SUCCESS, FAILED\n  errorMessage       String?\n  createdAt          DateTime      @default(now())\n}\n\nmodel Consultation {\n  id                     String            @id @default(uuid())\n  appointmentId          String            @unique\n  appointment            Appointment       @relation(fields: [appointmentId], references: [id], onDelete: Cascade)\n  notes                  String\n  followUpInfo           String?\n  prescriptionString     String?           @map(\"prescription\")\n  prescription           Prescription?\n  postVisitSummaryString String?           @map(\"postVisitSummary\")\n  postVisitSummary       PostVisitSummary?\n  createdAt              DateTime          @default(now())\n  updatedAt              DateTime          @updatedAt\n}\n\nmodel Prescription {\n  id             String             @id @default(uuid())\n  consultationId String             @unique\n  consultation   Consultation       @relation(fields: [consultationId], references: [id], onDelete: Cascade)\n  items          PrescriptionItem[]\n  createdAt      DateTime           @default(now())\n  updatedAt      DateTime           @updatedAt\n}\n\nmodel PrescriptionItem {\n  id             String       @id @default(uuid())\n  prescriptionId String\n  prescription   Prescription @relation(fields: [prescriptionId], references: [id], onDelete: Cascade)\n  medicineName   String\n  dosage         String\n  frequency      String\n  duration       String\n  instructions   String?\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n}\n\nmodel PostVisitSummary {\n  id                     String       @id @default(uuid())\n  consultationId         String       @unique\n  consultation           Consultation @relation(fields: [consultationId], references: [id], onDelete: Cascade)\n  patientFriendlySummary String?\n  medicationSchedule     Json? // Structured timing info\n  followUpSteps          String?\n  status                 String       @default(\"PENDING\") // PENDING, SUCCESS, FAILED\n  errorMessage           String?\n  createdAt              DateTime     @default(now())\n  updatedAt              DateTime     @updatedAt\n}\n\nmodel MedicationReminder {\n  id               String   @id @default(uuid())\n  patientId        String\n  patient          User     @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  medicineName     String\n  dosage           String\n  frequency        String // e.g. \"Once daily\", \"Twice daily\"\n  nextReminderTime DateTime\n  status           String   @default(\"ACTIVE\") // ACTIVE, SENT, INACTIVE\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n}\n\nmodel OutboxNotification {\n  id            String    @id @default(uuid())\n  type          String // EMAIL, CALENDAR\n  action        String // e.g. \"SEND_EMAIL\", \"CREATE_EVENT\", \"CANCEL_EVENT\"\n  payload       Json\n  attempts      Int       @default(0)\n  status        String    @default(\"PENDING\") // PENDING, PROCESSING, SENT, FAILED\n  errorMessage  String?\n  nextRetryTime DateTime?\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n}\n",
